/* Post-build check: prove a working self-hosted Lenis browser runtime was emitted. */
import { readFileSync, statSync, existsSync } from 'node:fs';
import assert from 'node:assert/strict';
import { join } from 'node:path';
const target=join(import.meta.dirname,'..','public','lenis-vendored.js');
assert.ok(existsSync(target),'The Lenis runtime bundle was not generated by prebuild');
const size=statSync(target).size;
assert.ok(size>=2500&&size<=130000,'Unexpected Lenis browser bundle size: '+size);
const code=readFileSync(target,'utf8');
assert.doesNotThrow(()=>new Function(code),'Generated Lenis bundle contains a syntax error');
assert.ok(code.includes('Lenis'),'Generated bundle appears to omit the Lenis runtime');
assert.ok(code.includes('scrollTo'),'Generated bundle must have scrollTo');
assert.ok(code.includes('destroy'),'Generated bundle must have cleanup support');
assert.ok(code.includes('wheel'),'Generated bundle must handle wheel smoothing');
assert.ok(!/https?:\/\/(?:unpkg|cdn\.jsdelivr)\./.test(code),'Runtime may not pull third-party scripts from CDN');
console.log('PASS: self-hosted Lenis browser bundle '+size+' bytes, valid JS, wheel smoothing, navigation and teardown included.');
